from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Parse events into tuples: (time, type, data)
        parsed = []
        for ev in events:
            typ, ts, val = ev
            parsed.append((int(ts), typ, val))
        # Sort by time, offline first for same time
        parsed.sort(key=lambda x: (x[0], 0 if x[1] == "OFFLINE" else 1))

        # Online status: True for online
        online = [True] * numberOfUsers
        # Track when a user comes back online
        comeback_time = {}
        mentions = [0] * numberOfUsers

        for ts, typ, val in parsed:
            # Process any pending comebacks up to current time
            to_back = [uid for uid, ct in list(comeback_time.items()) if ct <= ts]
            for uid in to_back:
                online[uid] = True
                del comeback_time[uid]

            if typ == "OFFLINE":
                uid = int(val)
                online[uid] = False
                comeback_time[uid] = ts + 60
            else:  # MESSAGE
                parts = val.split()
                if "ALL" in parts:
                    # mention all users
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif "HERE" in parts:
                    # mention online users
                    for i in range(numberOfUsers):
                        if online[i]:
                            mentions[i] += 1
                else:
                    # idX mentions, may have duplicates
                    for token in parts:
                        if token.startswith("id"):
                            uid = int(token[2:])
                            mentions[uid] += 1
        return mentions
