from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 300  # since |nums[i]-nums[j]| <= 299
        # best_len[i][d] = best length ending at i with last diff exactly d
        best_len = [ [0]* (max_diff+1) for _ in range(n) ]
        # suffix_max[i][d] = best length ending at i with last diff >= d
        suffix_max = [ [0]* (max_diff+2) for _ in range(n) ]  # extra slot for d=max_diff+1

        ans = 1
        for j in range(n):
            for i in range(j):
                d = abs(nums[j] - nums[i])
                # query best suffix from i for diffs >= d
                prev_len = suffix_max[i][d]
                cur_len = prev_len + 1 if prev_len > 0 else 2
                if cur_len > best_len[j][d]:
                    best_len[j][d] = cur_len
                    if cur_len > suffix_max[j][d]:
                        suffix_max[j][d] = cur_len
                        # update all smaller d positions
                        for dd in range(d-1, -1, -1):
                            if suffix_max[j][dd] >= cur_len:
                                break
                            suffix_max[j][dd] = cur_len
                if cur_len > ans:
                    ans = cur_len
        return ans
