class Solution:
    def zigzagTraversal(self, grid: list[list[int]]) -> list[int]:
        """
        Traverse the grid in a zigzag pattern while skipping every alternate cell.
        """
        result = []
        take = True  # whether to take the current cell
        for r, row in enumerate(grid):
            if r % 2 == 0:
                # left to right
                cols = range(len(row))
            else:
                # right to left
                cols = range(len(row) - 1, -1, -1)
            for c in cols:
                if take:
                    result.append(row[c])
                take = not take
        return result
