from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if threshold < 1:
            return -1
        # collect unique weights
        weights = sorted({w for _, _, w in edges})
        if not weights:
            return -1

        # build adjacency lists per weight threshold
        adj_rev = [[] for _ in range(n)]
        for u, v, w in edges:
            # store reverse edge v -> u
            adj_rev[v].append((u, w))

        def reachable(maxw: int) -> bool:
            vis = [False] * n
            q = deque([0])
            vis[0] = True
            while q:
                cur = q.popleft()
                for nxt, w in adj_rev[cur]:
                    if w <= maxw and not vis[nxt]:
                        vis[nxt] = True
                        q.append(nxt)
            return all(vis)

        lo, hi = 0, len(weights) - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if reachable(weights[mid]):
                ans = weights[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
