from typing import List
from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Collect all unique weights
        weights = sorted(set(w for _, _, w in edges))
        if not weights:
            return -1

        # Build reverse adjacency for all edges
        rev_adj = [[] for _ in range(n)]
        for u, v, w in edges:
            rev_adj[v].append((u, w))  # reversed edge: v -> u

        # Helper: check if all nodes can reach 0 using edges <= limit
        def can(limit: int) -> bool:
            visited = [False] * n
            q = deque([0])
            visited[0] = True
            while q:
                cur = q.popleft()
                for nxt, w in rev_adj[cur]:
                    if w <= limit and not visited[nxt]:
                        visited[nxt] = True
                        q.append(nxt)
            return all(visited)

        # Binary search over sorted weights
        lo, hi = 0, len(weights) - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(weights[mid]):
                ans = weights[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans
