class Solution:
    def maxAmount(self, initialCurrency, pairs1, rates1, pairs2, rates2):
        from collections import defaultdict

        def build_graph(pairs, rates):
            g = defaultdict(list)
            for (a, b), r in zip(pairs, rates):
                g[a].append((b, r))
                g[b].append((a, 1.0 / r))
            return g

        g1 = build_graph(pairs1, rates1)
        g2 = build_graph(pairs2, rates2)

        def max_rate(start, target, graph, memo):
            if start == target:
                return 1.0
            key = (start, target)
            if key in memo:
                return memo[key]
            best = 0.0
            for nxt, r in graph.get(start, []):
                val = r * max_rate(nxt, target, graph, memo)
                if val > best:
                    best = val
            memo[key] = best
            return best

        currencies = set()
        for a, b in pairs1 + pairs2:
            currencies.add(a)
            currencies.add(b)
        memo1 = {}
        memo2 = {}
        best = 1.0  # no conversion
        for c in currencies:
            rate1 = max_rate(initialCurrency, c, g1, memo1)
            if rate1 == 0.0:
                continue
            rate2 = max_rate(c, initialCurrency, g2, memo2)
            if rate2 == 0.0:
                continue
            amount = rate1 * rate2
            if amount > best:
                best = amount
        return best
