                best = NEG
                if dp[0][j-1][k] != NEG:
                    best = dp[0][j-1][k]
                val = coins[0][j]
                if val < 0:
                    if k > 0:
                        best = max(best, dp[0][j-1][k-1] if dp[0][j-1][k-1]!=NEG else NEG)
                else:
                    best = best + val
                dp[0][j][k] = best
        # first col
