                best = NEG
                if dp[i-1][0][k] != NEG:
                    best = dp[i-1][0][k]
                val = coins[i][0]
                if val < 0:
                    if k > 0:
                        best = max(best, dp[i-1][0][k-1] if dp[i-1][0][k-1]!=NEG else NEG)
                else:
                    best = best + val
                dp[i][0][k] = best
        # rest
        for i in range(1, m):
            for j in range(1, n):
                val = coins[i][j]
                for k in range(3):
                    best = NEG
                    if dp[i-1][j][k] != NEG:
                        best = dp[i-1][j][k]
                    if dp[i][j-1][k] != NEG:
                        best = max(best, dp[i][j-1][k])
                    if val < 0:
                        if k > 0:
                            if dp[i-1][j][k-1] != NEG:
                                best = max(best, dp[i-1][j][k-1])
                            if dp[i][j-1][k-1] != NEG:
                                best = max(best, dp[i][j-1][k-1])
                    else:
                        best = best + val
                    dp[i][j][k] = best
        return max(dp[m-1][n-1])
