class Solution:
    def maxLength(self, nums: List[int]) -> int:
        # Precompute prime masks for numbers 1..10
        prime_to_bit = {2: 1 << 0, 3: 1 << 1, 5: 1 << 2, 7: 1 << 3}
        def mask(x: int) -> int:
            m = 0
            for p in prime_to_bit:
                if x % p == 0:
                    m |= prime_to_bit[p]
            return m

        n = len(nums)
        left = 0
        cur_mask = 0
        best = 0

        for right in range(n):
            m = mask(nums[right])
            # Slide left until no conflict with current element
            while cur_mask & m:
                cur_mask ^= mask(nums[left])
                left += 1
            cur_mask |= m
            best = max(best, right - left + 1)

        return best
