from typing import List

class Solution:
    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)
        # compute existing max diff between known-known
        existing_max = 0
        for i in range(1, n):
            if nums[i] != -1 and nums[i-1] != -1:
                existing_max = max(existing_max, abs(nums[i] - nums[i-1]))

        # collect neighbor values of -1
        neighbors = []
        for i in range(n):
            if nums[i] == -1:
                if i > 0 and nums[i-1] != -1:
                    neighbors.append(nums[i-1])
                if i + 1 < n and nums[i+1] != -1:
                    neighbors.append(nums[i+1])

        # if no known neighbor (all -1), answer is 0
        if not neighbors:
            return 0

        neighbors.sort()

        # helper to check if all neighbors can be covered by <=2 intervals of length 2*mid
        def can_cover(mid: int) -> bool:
            # first interval covers from neighbors[0] to neighbors[0]+2*mid
            limit = neighbors[0] + 2 * mid
            # find first index > limit
            idx = 0
            while idx < len(neighbors) and neighbors[idx] <= limit:
                idx += 1
            if idx == len(neighbors):
                return True  # all covered by first interval
            # second interval
            limit = neighbors[idx] + 2 * mid
            while idx < len(neighbors) and neighbors[idx] <= limit:
                idx += 1
            return idx == len(neighbors)

        # binary search minimal mid
        lo, hi = 0, 10**9  # upper bound large enough
        while lo < hi:
            mid = (lo + hi) // 2
            if can_cover(mid):
                hi = mid
            else:
                lo = mid + 1
        r = lo

        return max(existing_max, r)
