import sys

def solve() -> None:
    input = sys.stdin.readline
    N, Q = map(int, input().split())
    instr = [tuple(input().split()) for _ in range(Q)]
    # convert T to int
    instr = [(h, int(t)) for h, t in instr]

    # distance function on ring avoiding other hand
    def cost(a: int, b: int, other: int) -> int:
        if a == b:
            return 0
        # clockwise distance
        if a < b:
            d1 = b - a
        else:
            d1 = N - a + b
        # counter-clockwise distance
        if a > b:
            d2 = a - b
        else:
            d2 = a + N - b
        # check if other lies on clockwise path (excluding start)
        def in_path(start, end, step, other):
            if start == end:
                return False
            cur = start
            while True:
                cur = (cur + step - 1) % N + 1
                if cur == end:
                    return False
                if cur == other:
                    return True
        # choose minimal valid
        best = 10**9
        if not in_path(a, b, 1, other):
            best = min(best, d1)
        if not in_path(a, b, -1, other):
            best = min(best, d2)
        return best

    # initial state: left=1, right=2
    # dp[other_pos] = cost, where other hand is at other_pos, moving hand at target
    # process first instruction
    h, t = instr[0]
    dp = {}
    if h == 'L':
        # left moves to t, right stays at 2
        dp[2] = cost(1, t, 2)
    else:
        dp[1] = cost(2, t, 1)

    prev_target = t

    for idx in range(1, Q):
        h, t = instr[idx]
        new_dp = {}
        if h == 'L':
            # left moves to t
            # if previous moving hand was left:
            if instr[idx-1][0] == 'L':
                for other in dp:
                    c = dp[other]
                    c2 = c + cost(prev_target, t, other)
                    if other not in new_dp or c2 < new_dp[other]:
                        new_dp[other] = c2
            else:
                # previous moving hand was right, now left is the other hand
                for other in dp:
                    c = dp[other]
                    # other is previous target, moving hand is at other
                    c2 = c + cost(other, t, prev_target)
                    if prev_target not in new_dp or c2 < new_dp[prev_target]:
                        new_dp[prev_target] = c2
        else:
            # right moves to t
            if instr[idx-1][0] == 'R':
                for other in dp:
                    c = dp[other]
                    c2 = c + cost(prev_target, t, other)
                    if other not in new_dp or c2 < new_dp[other]:
                        new_dp[other] = c2
            else:
                for other in dp:
                    c = dp[other]
                    c2 = c + cost(other, t, prev_target)
                    if prev_target not in new_dp or c2 < new_dp[prev_target]:
                        new_dp[prev_target] = c2
        dp = new_dp
        prev_target = t

    print(min(dp.values()))

if __name__ == "__main__":
    solve()
