import sys

def solve() -> None:
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))

    # Build segment tree for minimum query
    size = 1
    while size < N:
        size <<= 1
    seg = [10**9] * (2 * size)
    for i in range(N):
        seg[size + i] = A[i]
    for i in range(size - 1, 0, -1):
        seg[i] = seg[2 * i] if seg[2 * i] < seg[2 * i + 1] else seg[2 * i + 1]

    def first_leq(v: int) -> int:
        # return 0‑based index of first position with A_i <= v, or -1
        if seg[1] > v:
            return -1
        idx = 1
        while idx < size:
            if seg[2 * idx] <= v:
                idx = 2 * idx
            else:
                idx = 2 * idx + 1
        return idx - size

    out_lines = []
    for b in B:
        pos = first_leq(b)
        out_lines.append(str(pos + 1 if pos != -1 else -1))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
